## Final model



::: {.cell}

```{.r .cell-code}
#| label: final-model-table

final_model_table <- tidy(
  model_2,
  conf.int = TRUE,
  conf.level = .95
) |>
  mutate(
    term = recode(
      term,
      `(Intercept)` = "Intercept",
      age = "Age",
      genderFemale = "Gender: Female",
      Neuroticism = "Neuroticism",
      Conscientiousness = "Conscientiousness"
    ),
    # Format p-values for presentation
    p = case_when(
      p.value < .001 ~ "< .001",
      TRUE ~ sprintf("%.3f", p.value)
    )
  )

final_model_table |>
  select(
    term,
    estimate,
    std.error,
    statistic,
    conf.low,
    conf.high,
    p
  ) |>
  gt() |>
  tab_header(
    title = "Linear Regression Predicting Extraversion",
    subtitle = paste0(
      "N = ", nobs(model_2),
      "; R² = ", round(glance(model_2)$r.squared, 3)
    )
  ) |>
  cols_label(
    term = "Predictor",
    estimate = "b",
    std.error = "SE",
    statistic = "t",
    conf.low = "95% CI Low",
    conf.high = "95% CI High",
    p = "p"
  ) |>
  fmt_number(
    columns = c(
      estimate,
      std.error,
      statistic,
      conf.low,
      conf.high
    ),
    decimals = 2
  ) |>
  opt_row_striping()
```

